// Statement lines to C.
// Tells if the statement starts with the ret keyword.
bool nc_is_ret(NcContext *c, NcTokens items) {
    if (!nc_is(items.v[0], "ret")) {
        return 0;
    }
    if (items.n == 1) {
        return 1;
    }
    char *next = nc_text(c, items.v[1]);
    size_t n = strlen(next);
    if (next[0] == '=' || next[n - 1] == '=') {
        return 0;
    }
    return strcmp(next, ".") && strcmp(next, "->") && strcmp(next, "[") && strcmp(next, "++") && strcmp(next,
            "--");
}

